<script>
  const NS = "http://www.w3.org/2000/svg";
  const XMIN = -3.2, XMAX = 5.2, YMIN = -32, YMAX = 2;
  const L = 90, R = 870, T = 55, B = 555;

  const sx = x => L + (x - XMIN) / (XMAX - XMIN) * (R - L);
  const sy = y => T + (YMAX - y) / (YMAX - YMIN) * (B - T);
  const f = x => -x * x + 2 * x - 14;

  const $ = id => document.getElementById(id);
  const svg = $("board");

  let state = 1;
  let currentX = 3;
  let scanY = -20;
  let playing = false;
  let raf = null;
  let animDir = -1;
  let dwell = 0;
  let draggingPoint = false;

  function fmt(n, d = 2) {
    const v = Math.abs(n).toFixed(d);
    return (n < 0 ? "−" : "") + v;
  }

  function setAttrs(el, attrs) {
    for (const key in attrs) {
      el.setAttribute(key, attrs[key]);
    }
  }

  function svgNode(tag, attrs = {}, text = null) {
    const node = document.createElementNS(NS, tag);
    setAttrs(node, attrs);
    if (text !== null) node.textContent = text;
    return node;
  }

  function addTo(parent, tag, attrs = {}, text = null) {
    const node = svgNode(tag, attrs, text);
    parent.appendChild(node);
    return node;
  }

  function drawStatic() {
    let d = "";
    const step = 0.035;
    for (let x = XMIN; x <= XMAX + 1e-9; x += step) {
      const px = sx(x);
      const py = sy(f(x));
      d += (d === "" ? "M" : " L") + px.toFixed(2) + " " + py.toFixed(2);
    }
    $("curvePath").setAttribute("d", d);
    $("curveHalo").setAttribute("d", d);

    const maxY = sy(-13);

    setAttrs($("maxLine"), { x1: L, y1: maxY, x2: R, y2: maxY });
    setAttrs($("maxLineLabel"), { x: R - 12, y: maxY - 12 });

    setAttrs($("rangeShade"), {
      x: L,
      y: maxY,
      width: R - L,
      height: B - maxY
    });
    setAttrs($("rangeLine"), {
      x1: 910,
      y1: maxY,
      x2: 910,
      y2: B - 24
    });
    setAttrs($("rangeTickTop"), {
      x1: 898,
      y1: maxY,
      x2: 922,
      y2: maxY
    });
    setAttrs($("rangeTitle"), { x: 910, y: maxY - 13 });
    setAttrs($("rangeLabel13"), { x: 928, y: maxY + 5 });
    setAttrs($("rangeLabelInf"), { x: 928, y: B - 18 });

    const vx = sx(1);
    const vy = sy(-13);
    setAttrs($("vertexDot"), { cx: vx, cy: vy });
    setAttrs($("vertexLabel"), { x: vx + 14, y: vy - 12 });
    setAttrs($("symAxis"), { x1: vx, y1: T, x2: vx, y2: B });
    setAttrs($("symLabel"), { x: vx + 8, y: T + 24 });

    const grid = $("gridLayer");
    grid.innerHTML = "";

    for (let x = -3; x <= 5; x++) {
      addTo(grid, "line", {
        x1: sx(x),
        y1: T,
        x2: sx(x),
        y2: B,
        class: "grid-line"
      });
    }

    for (let y = -30; y <= 0; y += 5) {
      addTo(grid, "line", {
        x1: L,
        y1: sy(y),
        x2: R,
        y2: sy(y),
        class: "grid-line"
      });
    }

    const axis = $("axisLayer");
    axis.innerHTML = "";

    addTo(axis, "line", {
      x1: L,
      y1: sy(0),
      x2: R + 9,
      y2: sy(0),
      class: "axis-line",
      "marker-end": "url(#arrowAxis)"
    });

    addTo(axis, "line", {
      x1: sx(0),
      y1: B,
      x2: sx(0),
      y2: T - 9,
      class: "axis-line",
      "marker-end": "url(#arrowAxis)"
    });

    addTo(axis, "text", {
      x: R + 19,
      y: sy(0) + 6,
      class: "axis-name"
    }, "x");

    addTo(axis, "text", {
      x: sx(0) + 12,
      y: T - 8,
      class: "axis-name"
    }, "y");

    for (let x = -3; x <= 5; x++) {
      addTo(axis, "text", {
        x: sx(x),
        y: sy(0) + 24,
        class: "tick-label",
        "text-anchor": "middle"
      }, x === 0 ? "0" : fmt(x, 0));
    }

    for (let y = -5; y >= -30; y -= 5) {
      addTo(axis, "text", {
        x: sx(0) - 10,
        y: sy(y) + 5,
        class: "tick-label",
        "text-anchor": "end"
      }, fmt(y, 0));
    }

    addTo(axis, "text", {
      x: L + 8,
      y: B + 28,
      class: "note-label"
    }, "横、纵轴单位长度不同；图形只显示其中一段范围");
  }

  const stateData = [
    {
      graphTitle: "看整条曲线",
      stage: "观察",
      explainTitle: "整条曲线在说什么？",
      body: `<p>二次项系数是 <b>−1</b>，所以抛物线<b>开口向下</b>。拖动下方横坐标滑块，或直接拖动红点 P，比较它在不同位置的高度。</p>
        <div class="cue">观察：高度先升后降，顶点附近出现最高位置。</div>`,
      formula: `<div class="calc-line">原函数：<span class="eq-main">y = −x<sup>2</sup> + 2x − 14</span></div>
        <div class="formula-note">先不急着算：让图形告诉你最高处大概在哪里。</div>`
    },
    {
      graphTitle: "配方找顶点",
      stage: "找最高位置",
      explainTitle: "把“最高点”从式子里找出来",
      body: `<p>配方不改变函数，只把抛物线写成“顶点式”。绿色竖线是对称轴，绿色点是顶点。</p>
        <div class="cue">顶点式里，平方项会直接告诉我们最高高度。</div>`,
      formula: `<div class="calc-line">y = −x<sup>2</sup> + 2x − 14</div>
        <div class="calc-line">　= −(x<sup>2</sup> − 2x) − 14</div>
        <div class="calc-line">　= −[(x − 1)<sup>2</sup> − 1] − 14</div>
        <div class="calc-line strong-line">　= −(x − 1)<sup>2</sup> − 13</div>
        <div class="formula-note">顶点： (1, −13)</div>`
    },
    {
      graphTitle: "高度不会超过 −13",
      stage: "高度上限",
      explainTitle: "平方项给出高度上限",
      body: `<p>平方项 <b>(x−1)<sup>2</sup></b> 最小为 0；前面有负号，所以它让高度“只减不增”。</p>
        <div class="cue">当 x = 1 时，函数达到最高高度 −13。</div>`,
      formula: `<div class="calc-line">(x − 1)<sup>2</sup> ≥ 0</div>
        <div class="calc-line">⇒ −(x − 1)<sup>2</sup> ≤ 0</div>
        <div class="calc-line strong-line">⇒ y = −(x − 1)<sup>2</sup> − 13 ≤ −13</div>
        <div class="formula-note">等号在 x = 1 时取得。</div>`
    },
    {
      graphTitle: "扫描高度，确认没有遗漏",
      stage: "检查完整值域",
      explainTitle: "每个 y ≤ −13 都能取到",
      body: `<p>紫色水平线代表一个高度 y。拖动它：在 −13 以下，水平线与抛物线有两个交点；到 −13 时，只剩顶点。</p>
        <div class="cue">所以 y 不能高于 −13；而 −13 以下的每个高度都能被取到。</div>
        <div class="fine">动画只扫到 −30 是为了看清交点；抛物线还会继续向下无限延伸。</div>`,
      formula: `<div class="calc-line">y = −(x − 1)<sup>2</sup> − 13</div>
        <div class="calc-line">(x − 1)<sup>2</sup> = −13 − y</div>
        <div class="calc-line strong-line">x = 1 ± √(−13 − y)</div>
        <div class="formula-note">当且仅当 y ≤ −13，根号内 ≥ 0，方程有实数解。</div>`
    }
  ];

  function renderGraph() {
    const pointLayer = $("pointLayer");
    const scanLayer = $("scanLayer");
    const nearTop = Math.abs(scanY + 13) < 0.12;

    $("maxLineLayer").classList.toggle("is-hidden", state < 2 || (state === 4 && nearTop));
    $("vertexLayer").classList.toggle("is-hidden", state < 2);
    $("rangeLayer").classList.toggle("is-hidden", state < 3);
    scanLayer.classList.toggle("is-hidden", state !== 4);
    pointLayer.classList.toggle("is-hidden", state === 4);

    $("xSlider").value = currentX;
    $("ySlider").value = scanY;

    if (state < 4) {
      const yv = f(currentX);
      const px = sx(currentX);
      const py = sy(yv);
      const axisX = sx(0);
      const axisY0 = sy(0);

      setAttrs($("projH"), { x1: px, y1: py, x2: axisX, y2: py });
      setAttrs($("projV"), { x1: px, y1: py, x2: px, y2: axisY0 });
      setAttrs($("axisDot"), { cx: axisX, cy: py });
      setAttrs($("xAxisDot"), { cx: px, cy: axisY0 });
      setAttrs($("pointRing"), { cx: px, cy: py });
      setAttrs($("pointDot"), { cx: px, cy: py });
      setAttrs($("pointHit"), { cx: px, cy: py });

      const nearVertex = Math.abs(currentX - 1) < 0.06;
      const anchor = currentX > 4.4 ? "end" : "start";
      const dx = anchor === "end" ? -12 : 12;
      const dy = nearVertex ? 28 : -12;

      setAttrs($("pointLabel"), {
        x: px + dx,
        y: py + dy,
        "text-anchor": anchor
      });
      $("pointLabel").textContent = nearVertex ? "P = 顶点" : "P";

      setAttrs($("projYLabel"), {
        x: axisX + 10,
        y: py - 8,
        "text-anchor": "start"
      });
      $("projYLabel").textContent = "y = " + fmt(yv, 2);

      $("xReadout").innerHTML = `x = ${fmt(currentX, 2)}　y = ${fmt(yv, 2)}`;
    } else {
      const s = Math.sqrt(Math.max(0, -13 - scanY));
      const lineY = sy(scanY);
      const leftX = sx(1 - s);
      const rightX = sx(1 + s);

      setAttrs($("scanLine"), { x1: L, y1: lineY, x2: R, y2: lineY });
      setAttrs($("scanDotL"), { cx: leftX, cy: lineY });
      setAttrs($("scanDotR"), { cx: rightX, cy: lineY });

      $("scanDotR").style.display = s < 0.035 ? "none" : "";
      setAttrs($("scanLabel"), { x: L + 12, y: lineY - 10, "text-anchor": "start" });
      $("scanLabel").textContent = "y = " + fmt(scanY, 1);

      if (s < 0.035) {
        $("scanTangentLabel").style.display = "";
        setAttrs($("scanTangentLabel"), {
          x: sx(1) + 16,
          y: lineY + 30,
          "text-anchor": "start"
        });
        $("scanTangentLabel").textContent = "只与顶点相切";
      } else {
        $("scanTangentLabel").style.display = "none";
        $("scanTangentLabel").textContent = "";
      }

      if (s < 0.01) {
        $("yReadout").innerHTML = "y = −13.0：与顶点相切，x = 1";
      } else {
        $("yReadout").innerHTML =
          `y = ${fmt(scanY, 1)}：交点 x<sub>1</sub> = ${fmt(1 - s, 2)}，x<sub>2</sub> = ${fmt(1 + s, 2)}`;
      }
    }
  }

  function renderAll() {
    const data = stateData[state - 1];

    $("stateTitle").textContent = data.graphTitle;
    $("stepLabel").textContent = `步骤 ${state} / 4 · ${data.stage}`;
    $("explainTitle").textContent = data.explainTitle;
    $("explainBody").innerHTML = data.body;
    $("formulaBox").innerHTML = data.formula;

    $("answerPanel").classList.toggle("is-hidden", state !== 4);
    $("prevBtn").disabled = state === 1;
    $("nextBtn").disabled = state === 4;
    $("keyBtn").textContent = state === 4 ? "扫到 −13" : (state === 1 ? "到最高处" : "到顶点");

    document.querySelectorAll(".step-pill").forEach(btn => {
      btn.classList.toggle("active", Number(btn.dataset.state) === state);
    });

    $("xControl").classList.toggle("is-hidden", state === 4);
    $("yControl").classList.toggle("is-hidden", state !== 4);

    renderGraph();
  }

  function stopPlay() {
    playing = false;
    if (raf) {
      cancelAnimationFrame(raf);
      raf = null;
    }
    $("playBtn").textContent = "播放";
  }

  function startPlay() {
    if (playing) return;
    playing = true;
    dwell = 0;
    $("playBtn").textContent = "暂停";

    if (state === 4) {
      animDir = scanY < -13 ? 1 : -1;
    } else {
      animDir = currentX > 1 ? -1 : 1;
    }

    let last = performance.now();

    function frame(ts) {
      if (!playing) return;
      const dt = Math.min(50, ts - last) / 1000;
      last = ts;

      if (dwell > 0) {
        dwell -= dt;
      } else if (state === 4) {
        scanY += animDir * 4.0 * dt;
        if (scanY >= -13) {
          scanY = -13;
          animDir = -1;
          dwell = 0.16;
        } else if (scanY <= -30) {
          scanY = -30;
          animDir = 1;
          dwell = 0.16;
        }
      } else {
        currentX += animDir * 2.0 * dt;
        if (currentX >= XMAX) {
          currentX = XMAX;
          animDir = -1;
          dwell = 0.16;
        } else if (currentX <= XMIN) {
          currentX = XMIN;
          animDir = 1;
          dwell = 0.16;
        }
      }

      renderGraph();
      raf = requestAnimationFrame(frame);
    }

    raf = requestAnimationFrame(frame);
  }

  function setState(n) {
    if (n < 1 || n > 4) return;
    stopPlay();
    state = n;
    renderAll();
  }

  function clientToSvgPoint(evt) {
    const pt = svg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    return pt.matrixTransform(svg.getScreenCTM().inverse());
  }

  function movePointFromClient(evt) {
    if (state === 4) return;
    const p = clientToSvgPoint(evt);
    let x = XMIN + (p.x - L) / (R - L) * (XMAX - XMIN);
    x = Math.max(XMIN, Math.min(XMAX, x));
    currentX = Math.round(x * 100) / 100;
    renderGraph();
  }

  document.querySelectorAll(".step-pill").forEach(btn => {
    btn.addEventListener("click", () => setState(Number(btn.dataset.state)));
  });

  $("prevBtn").addEventListener("click", () => setState(state - 1));
  $("nextBtn").addEventListener("click", () => setState(state + 1));

  $("xSlider").addEventListener("input", e => {
    stopPlay();
    currentX = parseFloat(e.target.value);
    renderGraph();
  });

  $("ySlider").addEventListener("input", e => {
    stopPlay();
    scanY = parseFloat(e.target.value);
    renderGraph();
  });

  $("playBtn").addEventListener("click", () => {
    if (playing) {
      stopPlay();
    } else {
      startPlay();
    }
  });

  $("keyBtn").addEventListener("click", () => {
    stopPlay();
    if (state === 4) {
      scanY = -13;
    } else {
      currentX = 1;
    }
    renderGraph();
  });

  $("pointHit").addEventListener("pointerdown", e => {
    if (state === 4) return;
    stopPlay();
    draggingPoint = true;
    e.target.setPointerCapture(e.pointerId);
    movePointFromClient(e);
    e.preventDefault();
  });

  $("pointHit").addEventListener("pointermove", e => {
    if (!draggingPoint) return;
    movePointFromClient(e);
    e.preventDefault();
  });

  function endPointDrag(e) {
    draggingPoint = false;
    if (e.target.hasPointerCapture && e.target.hasPointerCapture(e.pointerId)) {
      e.target.releasePointerCapture(e.pointerId);
    }
  }

  $("pointHit").addEventListener("pointerup", endPointDrag);
  $("pointHit").addEventListener("pointercancel", endPointDrag);

  drawStatic();
  setState(1);
</script>
</body>
</html>
